mapper.select:
SELECT s.id, s.article_id, s.generation, s.seq, s.pool_round, s.user_uuid, u.username, s.content, s.merged_at
FROM relic_segments s LEFT JOIN `user` u ON u.uuid = s.user_uuid AND u.is_deleted =0
WHERE s.id = #{id}

SELECT s.id, s.article_id, s.generation, s.seq, s.pool_round, s.user_uuid, u.username, s.content, s.merged_at
FROM relic_segments s LEFT JOIN `user` u ON u.uuid = s.user_uuid AND u.is_deleted =0
WHERE s.article_id = #{articleId} AND s.generation = #{generation}
ORDER BY s.seq ASC LIMIT #{limit} OFFSET #{offset}
